import{_ as l,l as o,o as a,c as n,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"空间填充曲线","description":"","frontmatter":{"title":"空间填充曲线","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/space-filling-curve.md","filePath":"cs/space-filling-curve.md","lastUpdated":1789023840000}'),h={name:"cs/space-filling-curve.md"};function u(_,e,b,m,f,E){const i=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="空间填充曲线" tabindex="-1">空间填充曲线 <a class="header-anchor" href="#空间填充曲线" aria-label="Permalink to &quot;空间填充曲线&quot;">​</a></h1><div class="epigraph"><p>用一条连续折线串起网格单元，使空间相邻尽量在一维上也相邻；B 树与缓存看见的是这个线性序。</p><footer>—— 据 Hilbert, Über die stetige Abbildung einer Linie auf ein Flächenstück, 1891；Morton, A Computer Oriented Geodetic Data Base, 1966；Samet 整理</footer></div><p><a href="/cs/quadtree-octree">上一课</a> 给出象限。外存与<a href="/cs/locality-principle">局部性</a> 要的是一维扫描序。<a href="/cs/r-tree">R 树</a> 插入也可按 Hilbert 值排序打包。本课不切立方体。缺口是空间填充曲线：Morton（Z 序）与 Hilbert，把坐标比特交错或按旋转状态机编号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二维键 \\((x,y)\\) 若先排 \\(x\\) 再排 \\(y\\)，竖条相邻在一维上可能很远。Z 序：交错 \\(x,y\\) 的比特，四叉块在序上成一段。Hilbert：更保持邻接，构造用状态与旋转。缺口是<strong>多维网格上的双射编号</strong>，使范围查询变成一维上若干段（不是一段）。</p><p><span class="marginnote">Hilbert 1891 是分析学构造；数据库用离散网格版。Morton 1966 报告给出 Z 序。本课不把连续统曲线当作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Z 序：<code>code = interleave(x,y)</code>，比较即比较整数。范围查询：在 Z 空间上走，遇到出矩形则跳到下一可能码（clz 等技巧）。Hilbert：查表或迭代，编码稍贵，局部性通常更好。用于：把点排序后bulk-load R 树；缓存友好的矩阵分块遍历。</p>',8)),(a(),s(p,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20XY%5B%22%E7%BD%91%E6%A0%BC%20(x%2C%20y)%22%5D%20--%3E%20CURVE%5B%22Z%20%E6%88%96%20Hilbert%20%E7%A0%81%22%5D%0A%20%20CURVE%20--%3E%20BTREE%5B%22%E4%B8%80%E7%BB%B4%20B%20%E6%A0%91%20%2F%20%E6%8E%92%E5%BA%8F%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 k-d / R：曲线不替代几何剪枝，只提供序。高维 Z 序仍交错，段数变多。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四叉树叶的 Z 序恰好是深度优先象限序的一种。Hilbert 在块边界更少「空间近、序号远」。不要声称任意形状查询都变成单区间——正交矩形在 Z 序上是 \\(O(\\sqrt{n})\\) 段一类现象，分析视查询而定。</p><p>平衡堆与空间课序在此结束。下一单元字符串：后缀数组把「所有后缀的字典序」收成一维，不再是几何曲线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写空间填充曲线上的并行划分全部论文。不进入金融订单簿。字符串后缀排序是另一课序。</p><p>后课默认：需要把网格线性化时用 Z/Hilbert。后缀排序从后缀数组开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Z 序比特交错，Hilbert 更保邻接。</li><li>服务一维索引与 bulk-load，不是几何树的替代。</li><li>下一课程单元：后缀与哈希。</li><li>出处：Hilbert, 1891；Morton, 1966；Samet。</li></ul>',9))])}const A=l(h,[["render",u]]);export{B as __pageData,A as default};
